/* Alpha blending mode. */
#define GCREG_PE_ALPHA_CONFIG_ALPHA_MODE                                     3:0
#define GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_End                                   3
#define GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_Start                                 0
#define GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_Type                                U04
/* Use AQAlphaBlend state to configure the blending mode. */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_LEGACY                            0x0
/* C = Cs * Cd. */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_MULTIPLY                          0x1
/* C = Cs + Cd - Cs * Cd. */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_SCREEN                            0x2
/* If Cd <= 0.5: C = 2 * Cs * Cd, else C = 1 - 2 * (1 - Cs) * (1 - Cd). */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_OVERLAY                           0x3
/* C = min(Cs, Cd). */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_DARKEN                            0x4
/* C = max(Cs, Cd). */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_LIGHTEN                           0x5
/* If Cs <= 0.5: C = 2 * Cs * Cd, else C = 1 - 2 * (1 - Cs) * (1 - Cd). */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_HARDLIGHT                         0x6
/* C = abs(Cd - Cs). */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_DIFFERENCE                        0x7
/* C = Cs + Cd - 2 * Cs - Cd. */
#define   GCREG_PE_ALPHA_CONFIG_ALPHA_MODE_EXCLUSION                         0x8

/* Determine if alpha needs to be multiplied into the color channels. */
#define GCREG_PE_ALPHA_CONFIG_PRE_MULTIPLIED                                 4:4
#define GCREG_PE_ALPHA_CONFIG_PRE_MULTIPLIED_End                               4
#define GCREG_PE_ALPHA_CONFIG_PRE_MULTIPLIED_Start                             4
#define GCREG_PE_ALPHA_CONFIG_PRE_MULTIPLIED_Type                            U01
/* Don't multiply the alpha channel into the color channels. */
#define   GCREG_PE_ALPHA_CONFIG_PRE_MULTIPLIED_NORMAL                        0x0
/* Multiply the alpha channel into the color channels. */
#define   GCREG_PE_ALPHA_CONFIG_PRE_MULTIPLIED_PRE_MULTIPLIED                0x1

